const root=document.getElementById('app');
const prefersDark=(()=>{try{return localStorage.getItem('retro-theme')==='dark';}catch{return false;}})();
document.documentElement.dataset.theme=prefersDark?'dark':'light';
const S={theme:prefersDark?'dark':'light',authError:'',editMovie:null,series:[],seriesDetail:null,adminSeries:[],episodeQueue:null,data:null,me:null,view:'home',accountTab:'overview',modal:null,detail:null,payment:null,player:null,genre:'',decade:'',access:'',sort:'recent',query:'',filtered:null,stats:null,adminMovies:null,busy:false};
const money=(n)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(n||0)/100);
const fmtDate=(d)=>d?new Date(d).toLocaleDateString('pt-BR'):'—';
const esc=(x)=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const film=(id)=>S.data?.movies.find(m=>m.id===Number(id));
const user=()=>S.data?.user;
const allMovies=()=>S.data?.movies||[];
const iconSearch='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="7"/><path d="M20 20l-4-4"/></svg>';
async function api(url,method='GET',payload){
  const headers={};if(method!=='GET'&&S.data?.csrf)headers['X-CSRF-Token']=S.data.csrf;
  if(payload!==undefined){headers['Content-Type']='application/json';payload=JSON.stringify(payload);}
  let response;try{response=await fetch(url,{method,headers,body:payload,credentials:'same-origin'});}catch{throw new Error('Sem conexão com o Retro Play. Inicie pelo arquivo INICIAR_RETRO_PLAY.bat e abra http://127.0.0.1:4173 no navegador.');}
  let result={};try{result=await response.json();}catch{}
  if(!response.ok)throw new Error(result.error||`Erro HTTP ${response.status}`);
  return result;
}
let toaster;
function toast(message){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.role='status';el.textContent=message;document.body.append(el);clearTimeout(toaster);toaster=setTimeout(()=>el.remove(),4200);}
function showError(e){toast(e.message||'Não foi possível concluir.');}
async function reload(){S.data=await api('/api/bootstrap');S.series=(await api('/api/series')).series;if(user()){try{S.me=await api('/api/me');}catch{S.me=null;}}else S.me=null;}
function badge(m){const badges={free:'Grátis',subscription:'Assinatura',rental:`Aluguel ${money(m.rental_cents)}`,both:'Assinatura ou aluguel'};return badges[m.access_type]||'Conteúdo';}
function movieCard(m){const fav=S.me?.favorites?.includes(m.id);
  return `<article class="movie-card" tabindex="0" role="button" aria-label="Ver ${esc(m.title)}" data-action="details" data-id="${m.id}">
    <div class="movie-cover"><img src="${esc(m.poster)}" alt="Cartaz de ${esc(m.title)}" loading="lazy"><span class="card-badge">${esc(badge(m))}</span>
    <button type="button" class="card-heart ${fav?'saved':''}" data-action="favorite" data-id="${m.id}" aria-label="${fav?'Remover dos favoritos':'Adicionar aos favoritos'}">${fav?'♥':'♡'}</button></div>
    <div class="card-caption"><strong>${esc(m.title)}</strong><small>${m.year} · ${esc(m.genres?.[0]||'Cinema')} · ${m.age_rating===0?'Livre':m.age_rating+'+'}</small></div></article>`;
}
function section(title,subtitle,movies,key){if(!movies.length)return '';
return `<section class="section"><div class="section-head"><div><div class="section-kicker">${esc(subtitle)}</div><h2 class="section-title">${esc(title)}</h2></div><div class="section-controls"><button class="btn-round" title="Voltar" data-action="scroll" data-key="${key}" data-dir="-1">‹</button><button class="btn-round" title="Avançar" data-action="scroll" data-key="${key}" data-dir="1">›</button><button class="link-more" data-action="go" data-view="catalog">Ver tudo →</button></div></div><div class="rail" data-rail="${key}">${movies.map(movieCard).join('')}</div></section>`;}
function header(){const u=user();const isAdmin=u?.role==='admin';return `<header class="site-header"><div class="container header-inner">
  <button class="logo" data-action="go" data-view="home" aria-label="Retro Play - Início"><span class="logo-mark">▶</span><span class="logo-name">retro<span>play.</span></span></button>
  <nav class="main-nav" aria-label="Navegação principal">
    ${[['home','Início'],['catalog','Filmes'],['series','Séries'],['decades','Máquina do tempo'],['list','Minha lista']].map(([v,label])=>`<button class="nav-link ${S.view===v?'active':''}" data-action="go" data-view="${v}">${label}</button>`).join('')}
    ${isAdmin?'<button class="nav-link" data-action="go" data-view="admin">Admin</button>':''}
  </nav><div class="header-actions"><button class="search-toggle" data-action="searchModal" aria-label="Buscar filmes" title="Buscar filmes">${iconSearch}</button><button class="theme-toggle" data-action="theme" aria-label="${S.theme==='dark'?'Ativar modo claro':'Ativar modo noturno'}" title="${S.theme==='dark'?'Modo claro':'Modo noturno'}"><span aria-hidden="true">${S.theme==='dark'?'☀':'☾'}</span><span class="theme-label">${S.theme==='dark'?'Claro':'Noturno'}</span></button><form class="header-search" data-form="search" role="search">${iconSearch}<input aria-label="Buscar filmes" name="q" placeholder="Buscar sua próxima história" value="${esc(S.query)}"></form>
    ${u?`<button class="avatar-button" data-action="go" data-view="account"><span class="avatar-circle">${esc(S.me?.profile?.avatar||'🌸')}</span><span class="avatar-name">${esc(S.me?.profile?.name||u.displayName)}</span></button>`:'<button class="btn btn-secondary btn-sm" data-action="auth" data-mode="login">Entrar</button><button class="btn btn-ghost btn-sm signup-top" data-action="auth" data-mode="register">Cadastrar</button>'}
    <button class="btn btn-primary btn-sm" data-action="go" data-view="plans">Assine já</button></div></div></header>
    <nav class="mobile-nav" aria-label="Navegação móvel"><button data-action="go" data-view="home"><b>⌂</b>Início</button><button data-action="go" data-view="catalog"><b>▦</b>Filmes</button><button data-action="go" data-view="series"><b>▤</b>Séries</button><button data-action="go" data-view="decades"><b>◷</b>Décadas</button><button data-action="go" data-view="list"><b>♡</b>Minha lista</button><button data-action="${u?'go':'auth'}" ${u?'data-view="account"':'data-mode="register"'}><b>♙</b>${u?'Conta':'Cadastrar'}</button></nav>`;}
function homePage(){const movies=allMovies(),f=movies.find(m=>m.featured)||movies[0];if(!f)return '<section class="container panel">Nenhum filme cadastrado.</section>';
const classics=movies.filter(m=>m.year<2000),free=movies.filter(m=>m.access_type==='free'),rentals=movies.filter(m=>['rental','both'].includes(m.access_type)),sub=movies.filter(m=>['subscription','both'].includes(m.access_type));
return `<div class="container"><div class="hero-wrap"><div class="hero"><div class="hero-copy"><div class="eyebrow">O cinema que mora em você</div>
<h1>Histórias que <em>nunca saem</em> de cena.</h1><p class="hero-description">Uma viagem aconchegante pelo cinema de ontem, hoje e sempre. Encontre histórias, explore décadas e sinta a magia de dar play outra vez.</p>
<div class="hero-tagline"><span>Seu universo de filmes</span><span>Um toque de nostalgia</span></div>
<div class="hero-cta"><button class="btn btn-primary" data-action="play" data-id="${f.id}">▶ &nbsp; Assistir agora</button><button class="btn btn-secondary" data-action="details" data-id="${f.id}">Descobrir o filme ↗</button></div></div>
<div class="hero-visual"><div class="hero-halo"></div><div class="hero-poster"><img src="${esc(f.poster)}" alt="Cartaz de ${esc(f.title)}"></div><div class="hero-ticket"><small>SUA ENTRADA PARA A MAGIA</small><strong>admit one ♡</strong></div><div class="hero-stamp">feito para sonhar ✦</div><div class="hero-footnote">Retro Play • Edição de estreia</div></div></div></div>
<div class="statline"><span>✦ &nbsp; Um lugar para se apaixonar pelo cinema</span><i></i><span>Conteúdo de demonstração</span></div>
${section('Em destaque para você','Para dar play hoje',movies.slice(0,7),'hot')}
${seriesRail()}
${section('Tesouros de outras épocas','Volte no tempo',classics,'classic')}
<section class="decade-wrap"><div class="section-head"><div><div class="section-kicker">O tempo passa. O cinema fica.</div><h2 class="section-title">Escolha sua década favorita</h2><p class="section-sub">Uma máquina do tempo com um toque de magia.</p></div></div><div class="pill-row">${[1950,1960,1970,1980,1990,2000,2010,2020].map(d=>`<button class="chip" data-action="decade" data-decade="${d}">${d}s</button>`).join('')}</div></section>
${section('Para assistir sem assinar','Grátis e cheios de encanto',free,'free')}
${section('Só para assinantes','Um cantinho especial',sub,'subscription')}
${section('Uma sessão só sua','Alugue por filme',rentals,'rental')}
<section class="section"><div class="section-head"><div><div class="section-kicker">Explore de um jeito diferente</div><h2 class="section-title">A nostalgia também surpreende</h2></div></div>
<div class="feature-grid"><button class="feature-tile" data-action="random"><div class="feature-icon">✦</div><h3>Surpresa retrô</h3><p>Não sabe o que assistir? A gente escolhe uma história para você.</p></button><button class="feature-tile" data-action="go" data-view="decades"><div class="feature-icon">⏳</div><h3>Máquina do tempo</h3><p>Viaje pelas décadas e explore o cinema de cada época.</p></button><button class="feature-tile" data-action="roulette"><div class="feature-icon">✿</div><h3>Roleta de gêneros</h3><p>Deixe que a sorte escolha o próximo gênero da sua sessão.</p></button></div></section></div>`;}
function seriesRail(){return `<section class="section"><div class="section-head"><div><div class="section-kicker">Histórias em capítulos</div><h2 class="section-title">Antologias Retro Play</h2></div><button class="link-more" data-action="go" data-view="series">Todas as séries →</button></div><div class="series-grid">${S.series.map(x=>`<button class="series-card" data-action="seriesDetails" data-id="${x.id}"><img src="${esc(x.poster)}" alt="Cartaz de ${esc(x.title)}"><span><strong>${esc(x.title)}</strong><small>${x.episode_count} episódios de demonstração</small></span></button>`).join('')}</div></section>`;}
function seriesPage(){return `<div class="container"><section class="catalog-top"><div class="eyebrow">Retro Play / Séries</div><h1 class="page-title">Histórias para maratonar.</h1><p class="page-intro">Antologias e episódios de demonstração. Cada episódio usa um filme do catálogo e respeita as permissões de assinatura ou aluguel.</p></section>${seriesRail()}</div>`;}
function catalogPage(isDecade=false){const movies=S.filtered??allMovies();const title=isDecade?'Máquina do tempo':'Nosso catálogo';
return `<div class="container"><section class="catalog-top"><div class="eyebrow">Retro Play / Descobrir</div><h1 class="page-title">${title}</h1><p class="page-intro">Um catálogo de pequenas histórias demonstrativas. Escolha seu gênero, passeie por décadas e encontre seu próximo play.</p></section>
<div class="catalog-controls"><select id="genreFilter" class="select-control" aria-label="Gênero"><option value="">Todos os gêneros</option>${(S.data?.genres||[]).map(g=>`<option ${S.genre===g.name?'selected':''} value="${esc(g.name)}">${esc(g.name)}</option>`).join('')}</select>
<select id="decadeFilter" class="select-control" aria-label="Década"><option value="">Todas as décadas</option>${[1950,1960,1970,1980,1990,2000,2010,2020].map(d=>`<option ${S.decade==d?'selected':''} value="${d}">${d}s</option>`).join('')}</select>
<select id="accessFilter" class="select-control" aria-label="Tipo de acesso"><option value="">Todos os acessos</option>${[['free','Gratuitos'],['subscription','Assinatura'],['rental','Aluguel'],['both','Ambos']].map(([v,t])=>`<option ${S.access===v?'selected':''} value="${v}">${t}</option>`).join('')}</select>
<select id="sortFilter" class="select-control" aria-label="Ordenação">${[['recent','Mais recentes'],['oldest','Mais antigos'],['title','Título A–Z'],['popular','Mais assistidos']].map(([v,t])=>`<option ${S.sort===v?'selected':''} value="${v}">${t}</option>`).join('')}</select>
${S.query?`<button class="chip" data-action="clearSearch">Limpar busca: ${esc(S.query)} ×</button>`:''}</div>
<p class="section-sub">${movies.length} ${movies.length===1?'título encontrado':'títulos encontrados'}</p><section class="catalog-grid" style="margin-top:19px">${movies.length?movies.map(movieCard).join(''):'<div class="empty-state"><div class="empty-icon">✿</div>Não encontramos nenhum filme com esses filtros.<p>Tente outra década ou gênero.</p></div>'}</section></div>`;}
function listPage(){if(!user())return gate('Sua lista de favoritos','Entre na sua conta para guardar suas histórias favoritas.');const favorites=allMovies().filter(m=>S.me?.favorites?.includes(m.id));return `<div class="container"><div class="catalog-top"><div class="eyebrow">Sua coleção especial</div><h1 class="page-title">Minha lista ♡</h1><p class="page-intro">Um lugar para guardar os filmes que conquistaram seu coração.</p></div><div class="catalog-grid">${favorites.length?favorites.map(movieCard).join(''):'<div class="empty-state"><div class="empty-icon">♡</div>Seu cantinho ainda está vazio.<p>Toque no coração dos filmes para salvá-los.</p><button class="btn btn-primary" data-action="go" data-view="catalog">Explorar filmes</button></div>'}</div></div>`;}
function gate(title,text){return `<div class="container" style="padding-top:75px"><div class="panel" style="max-width:570px;margin:auto;text-align:center;padding:54px 35px"><p class="section-kicker">Um cantinho só seu</p><h1 class="page-title">${esc(title)}</h1><p class="page-intro" style="margin:16px auto 25px">${esc(text)}</p><button class="btn btn-primary" data-action="auth" data-mode="login">Entrar na minha conta</button></div></div>`;}
function plansPage(){return `<div class="container"><section class="catalog-top"><div class="eyebrow">Um ingresso para mais histórias</div><h1 class="page-title">Escolha seu jeito de assistir</h1><p class="page-intro">Assinatura mensal ou anual. E para quem prefere escolher um filme só, temos também aluguel individual.</p></section>
<div class="plans-grid">${(S.data?.plans||[]).map((p,i)=>`<div class="plan"><span class="plan-tag">${i?'Uma história que dura o ano todo':'Para experimentar'}</span><h3>${esc(p.name)}</h3><div><span class="price">${money(p.price_cents)}</span><span class="period"> / ${p.duration_days>100?'ano':'mês'}</span></div><ul><li>Catálogo para assinantes</li><li>Filmes em qualquer dispositivo</li><li>Perfis e favoritos</li><li>Continue de onde parou</li><li>Pagamentos de teste nesta versão</li></ul><button class="btn btn-primary" data-action="buy" data-kind="subscription" data-id="${p.id}">Selecionar plano</button></div>`).join('')}</div>
<div class="modal-note" style="max-width:850px;margin-top:23px"><strong>Ambiente demonstrativo:</strong> preços ilustrativos. Nenhum cartão é solicitado e nenhuma cobrança real será efetuada. O botão de aprovação simula um pagamento exclusivamente para testar as regras de acesso.</div></div>`;}
function accountPage(){if(!user())return gate('Minha conta','Crie sua conta ou entre para acompanhar suas sessões, perfis e assinaturas.');const me=S.me;if(!me)return '<div class="container panel">Carregando...</div>';
const tabs=[['overview','Visão geral','✦'],['profiles','Meus perfis','◌'],['continue','Continuar assistindo','▶'],['rentals','Aluguéis e pagamentos','⌁'],['achievements','Retro Recap','✿'],['settings','Segurança e dados','⚙']];
const body={
 overview:`<h2 class="section-title">Seu cantinho no Retro Play</h2><p class="section-sub">Olá, ${esc(me.profile?.name||user().displayName)}! Que bom ter você por aqui.</p><div class="section-divider"></div><div class="info-line"><span>Nome</span><strong>${esc(user().displayName)}</strong></div><div class="info-line"><span>E-mail</span><strong>${esc(user().email)}</strong></div><div class="info-line"><span>Plano atual</span><strong>${me.subscription?esc(me.subscription.plan_name):'Sem assinatura ativa'}</strong></div><div class="info-line"><span>Acesso até</span><strong>${fmtDate(me.subscription?.expires_at)}</strong></div>${me.subscription?`<p style="font-size:12px;color:#827074;margin-top:17px">Esta demonstração não renova assinaturas automaticamente.</p>${me.subscription.cancel_requested_at?'<span class="status status-pending">Cancelamento agendado</span>':`<button class="btn btn-secondary btn-sm" data-action="cancel" data-id="${me.subscription.id}">Cancelar ao fim do período</button>`}`:`<div style="margin-top:25px"><button class="btn btn-primary" data-action="go" data-view="plans">Conhecer planos</button></div>`}<div class="section-divider"></div><h3 class="section-title" style="font-size:24px">Suas histórias favoritas</h3><div class="stack" style="margin-top:18px">${(me.favorites||[]).slice(0,3).map(id=>miniMovie(film(id),'Favorito')).join('')||'<p class="section-sub">Nenhuma história favorita ainda.</p>'}</div>`,
 profiles:`<h2 class="section-title">Quem vai assistir?</h2><p class="section-sub">Cada perfil tem favoritos e histórico próprios.</p><div class="profile-grid">${(S.data?.profiles||[]).map(p=>`<button class="profile-option ${S.data.activeProfileId===p.id?'selected':''}" data-action="selectProfile" data-id="${p.id}"><span class="profile-emoji">${esc(p.avatar)}</span><span>${esc(p.name)}${p.is_kid?' · Infantil':''}</span></button>`).join('')}</div><button class="btn btn-secondary" data-action="newProfile">+ Novo perfil</button><p class="form-help" style="margin-top:19px">Até 5 perfis por conta. Perfil infantil restringe filmes com classificação acima de 10 anos.</p>`,
 continue:`<h2 class="section-title">De onde você parou</h2><p class="section-sub">Continue uma sessão com apenas um clique.</p><div class="stack" style="margin-top:24px">${(me.progress||[]).filter(p=>p.position_sec>0).map(p=>miniMovie(film(p.movie_id),`Pausado em ${Math.floor(p.position_sec)}s`,p.position_sec)).join('')||'<div class="empty-state"><div class="empty-icon">▶</div>Quando assistir a um filme, ele aparecerá aqui.</div>'}</div>`,
 rentals:`<h2 class="section-title">Aluguéis e pagamentos</h2><p class="section-sub">Acompanhe seu período de acesso e transações de teste.</p><div class="section-divider"></div><h3>Filmes alugados</h3><div class="stack">${(me.rentals||[]).map(r=>miniMovie(film(r.movie_id),r.expires_at?`Acesso até ${fmtDate(r.expires_at)}`:`Inicie até ${fmtDate(r.start_by)}`)).join('')||'<p class="section-sub">Você ainda não alugou nenhum filme.</p>'}</div><h3 style="margin-top:25px">Histórico de pagamentos</h3><div class="table-scroll"><table class="data-table"><thead><tr><th>Transação</th><th>Tipo</th><th>Valor</th><th>Status</th></tr></thead><tbody>${(me.payments||[]).map(p=>`<tr><td>#${p.id} · ${fmtDate(p.created_at)}</td><td>${p.kind==='rental'?'Aluguel':'Assinatura'}</td><td>${money(p.amount_cents)}</td><td><span class="status status-${esc(p.status)}">${esc(p.status)}</span></td></tr>`).join('')||'<tr><td colspan="4">Nenhuma transação ainda.</td></tr>'}</tbody></table></div>`,
 settings:`<h2 class="section-title">Configurações da conta</h2><p class="section-sub">Atualize seu nome e proteja seus dados de acesso.</p><div class="section-divider"></div><form data-form="accountName" class="stack" style="max-width:510px"><h3>Seu nome</h3><div class="form-field"><label for="displayName">Nome de exibição</label><input id="displayName" name="name" minlength="2" maxlength="70" required value="${esc(user().displayName)}"></div><button type="submit" class="btn btn-secondary">Salvar nome</button></form><div class="section-divider"></div><form data-form="password" class="stack" style="max-width:510px"><h3>Alterar senha</h3><div class="form-field"><label for="oldPass">Senha atual</label><input id="oldPass" name="oldPassword" type="password" autocomplete="current-password" required></div><div class="form-field"><label for="newPass">Nova senha (mínimo 10 caracteres)</label><input id="newPass" name="newPassword" type="password" minlength="10" autocomplete="new-password" required></div><div class="form-field"><label for="confirmNewPass">Confirme a nova senha</label><input id="confirmNewPass" name="confirmPassword" type="password" minlength="10" autocomplete="new-password" required></div><button type="submit" class="btn btn-primary">Alterar minha senha</button></form><div class="section-divider"></div><h3>Preferência visual</h3><p class="section-sub" style="margin-bottom:16px">Você pode alternar entre o tema bege e rosa e a versão noturna.</p><button class="btn btn-secondary" data-action="theme">${S.theme==='dark'?'☀ Ativar modo claro':'☾ Ativar modo noturno'}</button>`,
 achievements:`<h2 class="section-title">Seu Retro Recap ✿</h2><p class="section-sub">Pequenas memórias de tudo que você assistiu.</p><div class="admin-stats"><div class="stat"><span>Sessões iniciadas</span><b>${me.stats?.sessions||0}</b></div><div class="stat"><span>Minutos de vídeos</span><b>${Math.round((me.stats?.total_seconds||0)/60)}</b></div><div class="stat"><span>Gênero favorito</span><b style="font-size:19px">${esc(me.stats?.genre||'—')}</b></div><div class="stat"><span>Década favorita</span><b>${me.stats?.decade||'—'}</b></div></div><h3>Conquistas</h3><div class="stack">${(me.achievements||[]).map(a=>`<div class="achievement-row"><span class="achievement-icon">${esc(a.icon)}</span><div><strong>${esc(a.title)}</strong><small style="display:block;color:#927b7e">Conquistada em ${fmtDate(a.awarded_at)}</small></div></div>`).join('')||'<p class="section-sub">Sua primeira conquista aparece ao iniciar um filme.</p>'}</div>`
};return `<div class="container"><div class="catalog-top"><div class="eyebrow">Seu espaço pessoal</div><h1 class="page-title">Minha conta</h1></div><div class="account-grid"><aside class="account-sidebar"><div class="panel">${tabs.map(([key,label,sym])=>`<button class="account-tab ${S.accountTab===key?'active':''}" data-action="accountTab" data-tab="${key}">${sym} &nbsp; ${label}</button>`).join('')}<button class="account-tab" data-action="logout">↪ &nbsp; Sair da conta</button></div><div class="account-widget"><strong>Seu cinema particular ♡</strong><p>Histórias favoritas, sessões e conquistas em um só lugar.</p></div></aside><div class="panel">${body[S.accountTab]||body.overview}</div></div></div>`;}
function miniMovie(m,subtitle,progress){if(!m)return '';return `<div class="list-card"><img src="${esc(m.poster)}" alt=""><div style="flex:1"><strong>${esc(m.title)}</strong><p>${esc(subtitle)}</p>${progress!==undefined?`<div class="progress-bar"><div class="progress-fill" style="width:${Math.max(0,Math.min(100,progress/(m.duration_sec||300)*100))}%"></div></div>`:''}</div><button class="btn btn-secondary btn-sm" data-action="${progress!==undefined?'play':'details'}" data-id="${m.id}">${progress!==undefined?'▶ Retomar':'Ver'}</button></div>`;}
function adminPage(){if(user()?.role!=='admin')return gate('Área administrativa','Esta área é reservada a administradores autorizados.');if(!S.stats)return '<div class="container" style="padding:60px">Carregando painel...</div>';
const st=S.stats;return `<div class="container"><div class="catalog-top"><div class="eyebrow">Retro Play / Administração</div><h1 class="page-title">Painel administrativo</h1><p class="page-intro">Gerencie usuários, catálogo, conteúdos e o faturamento demonstrativo.</p></div>
<div class="admin-stats">${[['Usuários',st.users],['Filmes',st.movies],['Assinaturas ativas',st.activeSubscriptions],['Receita sandbox',money(st.revenueCents)]].map(([n,v])=>`<div class="stat"><span>${n}</span><b>${esc(v)}</b></div>`).join('')}</div>
<div class="panel"><h2 class="section-title">Cadastrar filme</h2><p class="section-sub" style="margin:9px 0 24px">Filme demonstrativo ou autorizado. Cadastre capa, dados e arquivo MP4.</p>
<form data-form="createMovie" class="form-grid"><div class="form-field"><label for="movieTitle">Título</label><input id="movieTitle" name="title" minlength="2" required placeholder="Nome do filme"></div>
<div class="form-field"><label for="movieSlug">Slug (sem espaços nem acentos)</label><input id="movieSlug" name="slug" required pattern="[a-z0-9]+(-[a-z0-9]+)*" placeholder="nome-do-filme"></div>
<div class="form-field full"><label for="movieSynopsis">Sinopse</label><textarea id="movieSynopsis" name="synopsis" placeholder="Sobre o que é esta história?"></textarea></div>
<div class="form-field"><label for="movieYear">Ano</label><input id="movieYear" type="number" name="year" value="2026" min="1900" max="2100"></div>
<div class="form-field"><label for="movieAccess">Acesso</label><select id="movieAccess" name="accessType"><option value="free">Gratuito</option><option value="subscription">Assinatura</option><option value="rental">Aluguel</option><option value="both">Ambos</option></select></div>
<div class="form-field"><label for="moviePrice">Aluguel (centavos)</label><input id="moviePrice" type="number" name="rentalCents" value="790" min="0"></div>
<div class="form-field"><label for="movieDuration">Duração (segundos)</label><input id="movieDuration" type="number" name="durationSec" value="300" min="1" required></div>
<div class="form-field"><label for="movieAge">Classificação indicativa</label><select id="movieAge" name="ageRating"><option value="0">Livre</option><option value="10">10 anos</option><option value="12">12 anos</option><option value="14">14 anos</option><option value="16">16 anos</option><option value="18">18 anos</option></select></div>
<div class="form-field"><label for="moviePoster">Capa (PNG, JPG ou WEBP, até 5 MB)</label><input id="moviePoster" type="file" name="posterFile" accept="image/png,image/jpeg,image/webp"></div>
<div class="form-field"><label for="movieVideo">Vídeo autorizado MP4 (até 120 MB)</label><input id="movieVideo" type="file" name="videoFile" accept="video/mp4"></div>
<div class="form-field"><label>Direção</label><input name="director" maxlength="200"></div><div class="form-field"><label>Elenco</label><input name="castText" maxlength="500"></div><div class="form-field full"><label>Gêneros separados por vírgulas</label><input name="genres" value="Drama" placeholder="Drama, Romance"></div><div class="form-field full"><button type="submit" class="btn btn-primary">+ Cadastrar filme</button><p class="form-help">Se não enviar arquivo, o filme reutiliza uma prévia demonstrativa. A upload não realiza transcodificação HLS automática.</p></div></form></div>
<div class="panel" style="margin-top:18px"><h2 class="section-title">Filmes no catálogo</h2><div style="margin-top:15px">${(S.adminMovies||[]).map(m=>`<div class="admin-row"><span><strong>${esc(m.title)}</strong><small style="display:block;color:#a1888d">${m.year} · ${esc(m.access_type)}</small></span><span>${m.published?'Publicado':'Oculto'}</span><button class="btn btn-secondary btn-sm" data-action="editMovie" data-id="${m.id}">Editar</button><button class="btn btn-secondary btn-sm" data-action="togglePublish" data-id="${m.id}" data-published="${m.published?'1':'0'}">${m.published?'Ocultar':'Publicar'}</button><button class="btn btn-ghost btn-sm" data-action="toggleFeatured" data-id="${m.id}" data-featured="${m.featured?'1':'0'}">${m.featured?'★ Destaque':'☆ Destacar'}</button></div>`).join('')}</div></div>
<div class="panel" style="margin-top:18px"><h2 class="section-title">Gerenciar séries</h2><p class="section-sub">Monte séries e temporadas associando filmes autorizados já cadastrados.</p><form data-form="createSeries" class="form-grid" style="margin-top:18px"><div class="form-field"><label>Nome da série</label><input name="title" required minlength="3" maxlength="100" placeholder="Ex.: Sessões do Tempo"></div><div class="form-field"><label>Descrição</label><input name="synopsis" maxlength="1000" placeholder="Sobre a série"></div><div class="form-field full"><button type="submit" class="btn btn-secondary">Criar série</button></div></form><div class="section-divider"></div><form class="form-grid" data-form="addEpisode"><div class="form-field"><label>Série</label><select name="seriesId" required>${(S.adminSeries||[]).map(x=>`<option value="${x.id}">${esc(x.title)}</option>`).join('')}</select></div><div class="form-field"><label>Filme usado como episódio</label><select name="movieId" required>${(S.adminMovies||[]).map(x=>`<option value="${x.id}">${esc(x.title)}</option>`).join('')}</select></div><div class="form-field"><label>Temporada</label><input type="number" name="season" value="1" min="1" max="99" required></div><div class="form-field"><label>Número do episódio</label><input type="number" name="number" value="1" min="1" max="999" required></div><div class="form-field full"><button class="btn btn-primary" type="submit">Adicionar episódio</button></div></form><div class="section-divider"></div>${(S.adminSeries||[]).map(x=>`<div class="admin-row"><span><strong>${esc(x.title)}</strong><small style="display:block">${x.episode_count} episódios · ${x.published?'Publicada':'Oculta'}</small></span><button data-action="toggleSeries" data-id="${x.id}" data-published="${x.published?1:0}" class="btn btn-secondary btn-sm">${x.published?'Ocultar':'Publicar'}</button></div>`).join('')}</div>
<div class="panel" style="margin-top:18px"><h2 class="section-title">Preços dos planos</h2><div class="stack" style="margin-top:17px">${(S.data?.plans||[]).map(p=>`<form class="admin-row" data-form="planPrice" data-id="${p.id}"><span><strong>${esc(p.name)}</strong></span><div class="form-field"><label>Valor em centavos</label><input style="max-width:170px" type="number" name="priceCents" min="0" value="${p.price_cents}" required></div><button class="btn btn-secondary btn-sm">Salvar</button></form>`).join('')}</div></div>
<div class="panel" style="margin-top:18px"><h2 class="section-title">Usuários registrados</h2><div class="table-scroll"><table class="data-table"><thead><tr><th>ID</th><th>Nome</th><th>E-mail</th><th>Papel</th></tr></thead><tbody>${(st.usersList||[]).map(x=>`<tr><td>#${x.id}</td><td>${esc(x.display_name)}</td><td>${esc(x.email)}</td><td>${esc(x.role)}</td></tr>`).join('')}</tbody></table></div></div>
<div class="panel" style="margin-top:18px"><h2 class="section-title">Transações de teste</h2><div class="table-scroll"><table class="data-table"><thead><tr><th>ID</th><th>Tipo</th><th>Valor</th><th>Estado</th></tr></thead><tbody>${(st.paymentsList||[]).map(p=>`<tr><td>#${p.id}</td><td>${esc(p.kind)}</td><td>${money(p.amount_cents)}</td><td><span class="status status-${p.status}">${esc(p.status)}</span></td></tr>`).join('')||'<tr><td colspan="4">Sem transações.</td></tr>'}</tbody></table></div></div></div>`;}
function footer(){return `<footer class="site-footer"><div class="container"><div class="footer-inner"><div><button class="logo" data-action="go" data-view="home"><span class="logo-mark">▶</span><span class="logo-name">retro<span>play.</span></span></button><p>Histórias que ficam. Memórias que voltam.</p></div><div class="footer-right">Uma experiência retrô, feita com carinho.<br>Catálogo e cobranças de demonstração. Conteúdos próprios de teste.</div></div><div class="footer-base">© 2026 Retro Play · Plataforma demonstrativa · Sem cobrança real · Respeite os direitos autorais.</div></div></footer>`;}
function render(){let page;
switch(S.view){case 'catalog':page=catalogPage(false);break;case 'series':page=seriesPage();break;case 'decades':page=catalogPage(true);break;case 'list':page=listPage();break;case 'plans':page=plansPage();break;case 'account':page=accountPage();break;case 'admin':page=adminPage();break;default:page=homePage();}
root.innerHTML=header()+`<main id="main">${page}</main>`+footer()+renderModal();document.title=`${{home:'Histórias que ficam',catalog:'Catálogo',series:'Séries',decades:'Máquina do tempo',list:'Minha lista',plans:'Assinaturas',account:'Minha conta',admin:'Admin'}[S.view]||'Retro Play'} · Retro Play`;
}
function renderModal(){if(!S.modal)return '';
let content='',wide=false,player=false;
if(S.modal==='series'&&S.seriesDetail){wide=true;const x=S.seriesDetail;content=`<div class="modal-content"><div class="section-kicker">Retro Play / Série original demonstrativa</div><h2 class="modal-heading">${esc(x.series.title)}</h2><p class="section-sub">${esc(x.series.synopsis)}</p><div class="series-episodes">${x.episodes.map((ep,i)=>`<div class="episode-row"><img src="${esc(ep.poster)}" alt=""><div><strong>T${ep.season} · E${ep.number} — ${esc(ep.title)}</strong><p>${esc(ep.synopsis)}</p><small>${esc(badge(ep))}</small></div><button class="btn btn-secondary btn-sm" data-action="${ep.access.allowed?'playEpisode':'details'}" data-index="${i}" data-id="${ep.movie_id}">${ep.access.allowed?'▶ Reproduzir':'Ver acesso'}</button></div>`).join('')}</div></div>`;}else if(S.modal==='search'){content=`<div class="modal-content"><div class="section-kicker">Encontre sua próxima história</div><h2 class="modal-heading">Buscar filmes</h2><form data-form="search" class="stack"><div class="form-field"><label for="mobileSearch">Título, diretor, elenco ou gênero</label><input id="mobileSearch" name="q" value="${esc(S.query)}" autocomplete="off" autofocus placeholder="O que você quer assistir?"></div><button class="btn btn-primary" type="submit">Buscar no catálogo</button></form></div>`;}else if(S.modal==='auth'){
const register=S.authMode==='register';content=`<div class="modal-content"><div class="auth-art">retro ♡ play</div><div class="section-kicker">Seu ingresso para o cinema</div><h2 class="modal-heading">${register?'Crie sua conta':'Que bom te ver de novo!'}</h2><form data-form="auth" class="stack" autocomplete="on" novalidate><div class="auth-error form-error" role="alert" ${S.authError?'':'hidden'}>${esc(S.authError||'')}</div>${register?'<div class="form-field"><label for="authName">Seu nome</label><input id="authName" name="name" minlength="2" maxlength="70" autocomplete="name" required></div>':''}<div class="form-field"><label for="authEmail">E-mail</label><input id="authEmail" type="email" name="email" autocomplete="email" required></div><div class="form-field"><label for="authPass">Senha</label><input id="authPass" type="password" name="password" minlength="${register?10:1}" autocomplete="${register?'new-password':'current-password'}" required></div>${register?'<div class="form-field"><label for="authConfirmPass">Confirme sua senha</label><input id="authConfirmPass" type="password" name="confirmPassword" minlength="10" autocomplete="new-password" required></div><p class="form-help">Use pelo menos 10 caracteres na sua senha.</p>':''}<label class="check-row"><input type="checkbox" data-password-toggle> Mostrar senha</label><button class="btn btn-primary" type="submit">${register?'Criar minha conta':'Entrar'}</button></form><p class="auth-switch">${register?'Já tem conta?':'Ainda não tem uma conta?'} <button data-action="auth" data-mode="${register?'login':'register'}">${register?'Entrar agora':'Cadastre-se'}</button></p></div>`;
}else if(S.modal==='details'&&S.detail){wide=true;const m=S.detail.movie,a=S.detail.access,rev=S.detail.reviews;
content=`<div class="modal-content"><div class="detail-hero"><img class="detail-poster" src="${esc(m.poster)}" alt="Cartaz de ${esc(m.title)}"><div><p class="section-kicker">Retro Play • Uma história para você</p><h2 class="detail-title">${esc(m.title)}</h2><div class="detail-meta"><span>${m.year}</span><span>${m.age_rating?m.age_rating+'+':'Livre'}</span><span>${esc(m.genres?.join(' • '))}</span><span>${m.demo?'Prévia original':'Filme'}</span></div><p class="detail-synopsis">${esc(m.synopsis)}</p><p class="form-help">Direção: ${esc(m.director||'Não informada')} · Avaliação: ${m.rating?`${m.rating} / 5`:'Seja a primeira pessoa a avaliar'}</p>
<div class="detail-actions">${a.allowed?`<button class="btn btn-primary" data-action="play" data-id="${m.id}">▶ Assistir agora</button>`:a.reason==='Bloqueado pelo perfil infantil'?'<span class="modal-note">Restrito pelo perfil infantil.</span>':`<button class="btn btn-primary" data-action="${user()?'go':'auth'}" data-view="plans" data-mode="login">Conhecer assinatura</button>${['rental','both'].includes(m.access_type)?`<button class="btn btn-secondary" data-action="buy" data-kind="rental" data-id="${m.id}">Alugar ${money(m.rental_cents)}</button>`:''}`}
<button class="btn btn-secondary" data-action="favorite" data-id="${m.id}">${S.me?.favorites?.includes(m.id)?'♥ Salvo':'♡ Minha lista'}</button></div><p class="form-help">${a.allowed?'Disponível para sua sessão.':'Este título não está incluído no seu acesso atual.'}</p></div></div>
<div class="section-divider"></div><h3 class="section-title" style="font-size:25px">Avaliações</h3>${user()?`<form data-form="review" data-id="${m.id}" class="form-grid" style="margin:17px 0"><div class="form-field"><label>Sua nota</label><select name="stars"><option value="5">★★★★★ — 5</option><option value="4">★★★★☆ — 4</option><option value="3">★★★☆☆ — 3</option><option value="2">★★☆☆☆ — 2</option><option value="1">★☆☆☆☆ — 1</option></select></div><div class="form-field"><label>Comentário (opcional)</label><input name="body" maxlength="600" placeholder="O que você achou?"></div><div class="form-field full"><button class="btn btn-secondary btn-sm" type="submit">Salvar avaliação</button></div></form>`:'<p class="section-sub">Entre na sua conta para avaliar.</p>'}<div>${rev.length?rev.map(x=>`<div class="review"><strong>${esc(x.name)}</strong><small>${'★'.repeat(x.stars)}${'☆'.repeat(5-x.stars)}</small><p>${esc(x.body||'Avaliação sem comentário.')}</p></div>`).join(''):'<p class="section-sub">Ainda não há avaliações.</p>'}</div></div>`;
}else if(S.modal==='editMovie'&&S.editMovie){wide=true;const m=S.editMovie;content=`<div class="modal-content"><div class="section-kicker">Retro Play / Catálogo</div><h2 class="modal-heading">Editar ${esc(m.title)}</h2><form class="form-grid" data-form="editMovie" data-id="${m.id}"><div class="form-field"><label>Título</label><input name="title" value="${esc(m.title)}" required minlength="2" maxlength="100"></div><div class="form-field"><label>Ano</label><input name="year" type="number" value="${m.year}" min="1900" max="2100" required></div><div class="form-field full"><label>Sinopse</label><textarea name="synopsis">${esc(m.synopsis)}</textarea></div><div class="form-field"><label>Direção</label><input name="director" value="${esc(m.director)}" maxlength="200"></div><div class="form-field"><label>Elenco</label><input name="castText" value="${esc(m.cast_text)}" maxlength="500"></div><div class="form-field"><label>Gêneros separados por vírgulas</label><input name="genres" value="${esc((m.genres||[]).join(', '))}" placeholder="Drama, Romance"></div><div class="form-field"><label>Tipo de acesso</label><select name="accessType">${[['free','Grátis'],['subscription','Assinatura'],['rental','Aluguel'],['both','Ambos']].map(([k,t])=>`<option value="${k}" ${m.access_type===k?'selected':''}>${t}</option>`).join('')}</select></div><div class="form-field"><label>Preço de aluguel (centavos)</label><input name="rentalCents" type="number" min="0" value="${m.rental_cents}"></div><div class="form-field"><label>Duração (segundos)</label><input name="durationSec" type="number" min="1" value="${m.duration_sec}"></div><div class="form-field"><label>Classificação indicativa</label><select name="ageRating">${[0,10,12,14,16,18].map(a=>`<option value="${a}" ${m.age_rating===a?'selected':''}>${a?a+' anos':'Livre'}</option>`).join('')}</select></div><div class="form-field"><label>Dias para iniciar aluguel</label><input type="number" min="1" name="rentalStartDays" value="${m.rental_start_days}"></div><div class="form-field"><label>Horas após o primeiro play</label><input type="number" min="1" name="rentalWatchHours" value="${m.rental_watch_hours}"></div><div class="form-field full"><button type="submit" class="btn btn-primary">Salvar alterações</button></div></form></div>`;
}else if(S.modal==='payment'&&S.payment){const p=S.payment;content=`<div class="modal-content"><div class="auth-art">Ingresso retrô ✦</div><div class="section-kicker">Checkout de demonstração</div><h2 class="modal-heading">Confirme sua sessão</h2><div class="info-line"><span>Produto</span><strong>${p.kind==='subscription'?'Assinatura':'Aluguel individual'}</strong></div><div class="info-line"><span>Valor</span><strong>${money(p.amountCents)}</strong></div><div class="info-line"><span>Pagamento</span><strong>Sandbox interno · Sem cobrança</strong></div><div class="modal-note"><strong>Pagamento fictício.</strong> Os botões abaixo servem somente para simular uma resposta do processador de pagamentos. Não há uso de cartão ou dinheiro real.</div><div class="stack"><button class="btn btn-primary" data-action="finishPayment" data-status="approve">✓ Simular aprovação</button><button class="btn btn-secondary" data-action="finishPayment" data-status="decline">Simular recusa</button></div></div>`;
}else if(S.modal==='player'&&S.player){wide=true;player=true;const m=film(S.player.movieId);content=`<div class="player-bar"><div><strong>${esc(m?.title||'Retro Play')}</strong><small style="display:block;color:#c6adb6">${m?.demo?'Prévia original de demonstração':'Reproduzindo'}</small></div><div class="player-actions"><button data-action="speed" title="Velocidade de reprodução">1× Velocidade</button>${S.player.nextEpisode?'<button data-action="nextEpisode">▶ Próximo episódio</button>':''}<button data-action="cinema">◩ Modo cinema</button><button data-action="vhs">▥ VHS</button><button data-action="closeModal">✕ Fechar</button></div></div><video id="moviePlayer" class="player-video" controls playsinline preload="auto" src="${esc(S.player.videoUrl)}"><track kind="subtitles" src="/assets/captions/demo.vtt" srclang="pt" label="Português" default></video><div class="player-bar"><span style="font-size:12px;color:#cbb7be">Assista diretamente no Retro Play. Progresso salvo automaticamente para usuários.</span></div>`;
}else if(S.modal==='newProfile'){content=`<div class="modal-content"><div class="section-kicker">Seja bem-vindo</div><h2 class="modal-heading">Novo perfil</h2><form class="stack" data-form="newProfile"><div class="form-field"><label>Nome do perfil</label><input name="name" minlength="2" maxlength="40" required></div><div class="form-field"><label>Escolha um avatar</label><select name="avatar"><option value="🌸">🌸 Florzinha</option><option value="🌷">🌷 Tulipa</option><option value="🍿">🍿 Pipoca</option><option value="⭐">⭐ Estrela</option><option value="📼">📼 VHS</option></select></div><label class="check-row"><input name="isKid" type="checkbox"> Perfil infantil (até 10 anos)</label><button class="btn btn-primary" type="submit">Criar perfil</button></form></div>`;}
return `<div class="modal-backdrop" data-action="closeOnBackdrop"><div class="modal ${wide?'wide':''} ${player?'player-modal':''}" role="dialog" aria-modal="true" aria-label="Retro Play"><${player?'div':'button'} ${player?'style="display:none"':'class="modal-close" aria-label="Fechar" data-action="closeModal"'}>${player?'':'×'}</${player?'div':'button'}>${content}</div></div>`;
}
async function go(view){if(view==='account'&&!user()){openAuth('login');return;}if(view==='list'&&!user()){openAuth('login');return;}S.view=view;S.modal=null;S.detail=null;document.body.classList.remove('cinema','vhs');if(['catalog','decades'].includes(view))await updateCatalog();if(view==='admin'&&user()?.role==='admin')await loadAdmin();render();window.scrollTo({top:0,behavior:'smooth'});}
function openAuth(mode='login'){S.authMode=mode;S.authError='';S.modal='auth';render();setTimeout(()=>document.getElementById(mode==='register'?'authName':'authEmail')?.focus(),0);}
async function seriesDetails(id){try{S.seriesDetail=await api(`/api/series/${id}`);S.modal='series';render();}catch(e){showError(e);}}
async function details(mid){try{S.detail=await api(`/api/movies/${mid}`);S.modal='details';render();}catch(e){showError(e);}}
async function updateCatalog(){const params=new URLSearchParams();if(S.query)params.set('q',S.query);if(S.genre)params.set('genre',S.genre);if(S.decade)params.set('decade',S.decade);if(S.access)params.set('access',S.access);if(S.sort)params.set('sort',S.sort);try{S.filtered=(await api('/api/movies?'+params)).movies;}catch(e){showError(e);}}
async function loadAdmin(){try{[S.stats,S.adminMovies,S.adminSeries]=await Promise.all([api('/api/admin/stats'),api('/api/admin/movies').then(x=>x.movies),api('/api/admin/series').then(x=>x.series)]);}catch(e){showError(e);}}
async function refreshKeepModal(){const oldModal=S.modal;await reload();if(oldModal==='details'&&S.detail)S.detail=await api(`/api/movies/${S.detail.movie.id}`);render();}
function closeModal(){if(S.player){saveProgress().catch(()=>{});S.player=null;}S.modal=null;document.body.classList.remove('cinema','vhs');render();}
async function watch(mid){try{const result=await api(`/api/movies/${mid}/play`,'POST',{});S.player={movieId:Number(mid),videoUrl:result.videoUrl,resumeAt:result.resumeAt,lastSaved:-99,nextEpisode:S.episodeQueue?.episodes?.[S.episodeQueue.index+1]?.movie_id||null};S.modal='player';render();const video=document.getElementById('moviePlayer');if(!video)return;if(result.hlsUrl && video.canPlayType('application/vnd.apple.mpegurl')) video.src=result.hlsUrl;
video.addEventListener('loadedmetadata',()=>{if(result.resumeAt>0&&result.resumeAt<video.duration-1)video.currentTime=result.resumeAt;});
video.addEventListener('timeupdate',()=>{if(!S.player)return;if(video.currentTime-S.player.lastSaved>5){S.player.lastSaved=video.currentTime;saveProgress().catch(()=>{});}});
video.addEventListener('pause',()=>saveProgress().catch(()=>{}));video.addEventListener('ended',()=>saveProgress().catch(()=>{}));
video.play().catch(()=>{});if(user()){S.me=await api('/api/me');}
}catch(e){showError(e);if(e.message.toLowerCase().includes('login')||e.message.toLowerCase().includes('entre'))openAuth('login');}}
async function saveProgress(){const v=document.getElementById('moviePlayer');if(!v||!S.player||!user())return;await api('/api/progress','POST',{movieId:S.player.movieId,positionSec:Math.max(0,v.currentTime||0)});}
async function buy(kind,id){if(!user()){openAuth('login');return;}try{const result=await api('/api/payments','POST',{kind,productId:Number(id)});S.payment=result.payment;S.modal='payment';render();}catch(e){showError(e);}}
async function finishPayment(status){try{await api(`/api/sandbox/payments/${S.payment.id}/${status}`,'POST',{});S.modal=null;S.payment=null;await reload();render();toast(status==='approve'?'Pagamento de teste aprovado. Acesso atualizado.':'Pagamento de teste recusado. Nenhuma cobrança foi feita.');}catch(e){showError(e);}}
async function toggleFavorite(mid){if(!user()){openAuth('login');return;}try{const result=await api('/api/favorites','POST',{movieId:Number(mid)});S.me=await api('/api/me');render();toast(result.favorite?'Adicionado à sua lista ♡':'Removido da sua lista.');}catch(e){showError(e);}}
function randomPick(items){return items.length?items[Math.floor(Math.random()*items.length)]:null;}
async function handleAction(button,event){const action=button.dataset.action,mid=Number(button.dataset.id),view=button.dataset.view;
if(action==='go')return go(view);
if(action==='auth')return openAuth(button.dataset.mode);
if(action==='theme'){S.theme=S.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=S.theme;try{localStorage.setItem('retro-theme',S.theme);}catch{}return render();}
if(action==='searchModal'){S.modal='search';render();document.getElementById('mobileSearch')?.focus();return;}
if(action==='details')return details(mid);
if(action==='seriesDetails')return seriesDetails(mid);
if(action==='playEpisode'){S.episodeQueue={episodes:S.seriesDetail.episodes,index:Number(button.dataset.index)};return watch(mid);}
if(action==='nextEpisode'){const next=S.player?.nextEpisode;if(next){S.episodeQueue.index++;return watch(next);}return;}
if(action==='play'){S.episodeQueue=null;return watch(mid);}
if(action==='favorite')return toggleFavorite(mid);
if(action==='buy')return buy(button.dataset.kind,mid);
if(action==='finishPayment')return finishPayment(button.dataset.status);
if(action==='closeModal')return closeModal();
if(action==='closeOnBackdrop'&&event.target===button)return closeModal();
if(action==='scroll'){document.querySelector(`[data-rail="${button.dataset.key}"]`)?.scrollBy({left:Number(button.dataset.dir)*600,behavior:'smooth'});return;}
if(action==='clearSearch'){S.query='';await updateCatalog();return render();}
if(action==='decade'){S.decade=button.dataset.decade;S.query='';S.genre='';S.access='';return go('decades');}
if(action==='random'){const items=allMovies().filter(m=>m.access_type==='free'||(S.me?.subscription&&['subscription','both'].includes(m.access_type))||S.me?.rentals?.some(r=>r.movie_id===m.id));const m=randomPick(items);if(m)return details(m.id);return toast('Nenhum título disponível neste momento.');}
if(action==='roulette'){S.genre=randomPick(S.data?.genres||[])?.name||'';S.decade='';S.access='';return go('catalog');}
if(action==='accountTab'){S.accountTab=button.dataset.tab;return render();}
if(action==='newProfile'){S.modal='newProfile';return render();}
if(action==='selectProfile'){try{await api('/api/profiles/select','POST',{profileId:mid});await reload();render();toast('Perfil selecionado.');}catch(e){showError(e);}return;}
if(action==='logout'){try{await api('/api/auth/logout','POST',{});S.modal=null;S.view='home';await reload();render();toast('Você saiu da sua conta.');}catch(e){showError(e);}return;}
if(action==='cinema'){document.body.classList.toggle('cinema');return;}
if(action==='vhs'){document.body.classList.toggle('vhs');return;}
if(action==='speed'){const v=document.getElementById('moviePlayer');if(v){const speeds=[1,1.25,1.5,2];v.playbackRate=speeds[(speeds.indexOf(v.playbackRate)+1)%speeds.length];button.textContent=`${v.playbackRate}× Velocidade`;}return;}
if(action==='cancel'){try{await api(`/api/subscriptions/${mid}/cancel`,'POST',{});await reload();render();toast('Renovação desativada. Acesso pago continua até o fim do período.');}catch(e){showError(e);}return;}
if(action==='editMovie'){S.editMovie=S.adminMovies?.find(x=>x.id===mid)||null;if(S.editMovie){S.modal='editMovie';render();}return;}
if(action==='toggleSeries'){try{await api(`/api/admin/series/${mid}`,'PATCH',{published:button.dataset.published!=='1'});await reload();await loadAdmin();render();toast('Publicação da série atualizada.');}catch(e){showError(e);}return;}
if(action==='togglePublish'||action==='toggleFeatured'){const field=action==='togglePublish'?'published':'featured',was=button.dataset[field]==='1';try{await api(`/api/admin/movies/${mid}`,'PATCH',{[field]:!was});await reload();await loadAdmin();render();toast('Filme atualizado.');}catch(e){showError(e);}return;}
}
async function upload(file,kind){if(!file)return null;const max=kind==='poster'?5*1024*1024:120*1024*1024;if(file.size>max)throw new Error('Arquivo excede o limite permitido.');
const headers={'Content-Type':file.type,'X-CSRF-Token':S.data?.csrf||''};const res=await fetch(`/api/admin/upload?kind=${kind}`,{method:'POST',headers,body:file,credentials:'same-origin'});
const out=await res.json();if(!res.ok)throw new Error(out.error||'Falha no upload.');return out.path;}
async function handleForm(form){const type=form.dataset.form,data=new FormData(form);try{
if(type==='search'){S.query=String(data.get('q')||'').trim();S.decade='';S.genre='';S.access='';return go('catalog');}
if(type==='auth'){
 const isReg=S.authMode==='register';
 const name=String(data.get('name')||'').trim(),email=String(data.get('email')||'').trim().toLowerCase(),password=String(data.get('password')||'');
 if(isReg&&(name.length<2||name.length>70))throw new Error('Informe seu nome com pelo menos 2 caracteres.');
 if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw new Error('Informe um e-mail válido, como nome@exemplo.com.');
 if(isReg&&(password.length<10||password.length>200))throw new Error('A senha precisa ter pelo menos 10 caracteres.');
 if(!password)throw new Error('Digite sua senha.');
 if(isReg&&password!==String(data.get('confirmPassword')||''))throw new Error('As senhas não coincidem.');
 await api(isReg?'/api/auth/register':'/api/auth/login','POST',{name,email,password});
 await reload();S.modal=null;render();toast(isReg?'Sua conta foi criada! ♡':'Bem-vindo de volta!');return;
}
if(type==='editMovie'){
const genres=String(data.get('genres')||'').split(',').map(x=>x.trim()).filter(Boolean);
await api(`/api/admin/movies/${Number(form.dataset.id)}`,'PATCH',{
 title:String(data.get('title')),synopsis:String(data.get('synopsis')||''),director:String(data.get('director')||''),castText:String(data.get('castText')||''),
 year:Number(data.get('year')),durationSec:Number(data.get('durationSec')),ageRating:Number(data.get('ageRating')),
 accessType:String(data.get('accessType')),rentalCents:Number(data.get('rentalCents')),
 rentalStartDays:Number(data.get('rentalStartDays')),rentalWatchHours:Number(data.get('rentalWatchHours')),genres});
S.modal=null;S.editMovie=null;await reload();await loadAdmin();render();toast('Filme atualizado com sucesso.');return;
}
if(type==='createSeries'){await api('/api/admin/series','POST',{title:String(data.get('title')||''),synopsis:String(data.get('synopsis')||'')});await reload();await loadAdmin();render();toast('Série criada.');return;}
if(type==='addEpisode'){await api(`/api/admin/series/${Number(data.get('seriesId'))}/episodes`,'POST',{movieId:Number(data.get('movieId')),season:Number(data.get('season')),number:Number(data.get('number'))});await reload();await loadAdmin();render();toast('Episódio adicionado.');return;}
if(type==='accountName'){await api('/api/account','PATCH',{displayName:String(data.get('name')||'')});await reload();render();toast('Nome atualizado.');return;}
if(type==='password'){if(data.get('newPassword')!==data.get('confirmPassword'))throw new Error('As senhas não coincidem.');await api('/api/account/password','POST',{currentPassword:data.get('oldPassword'),newPassword:data.get('newPassword')});form.reset();toast('Senha atualizada com sucesso.');return;}
if(type==='newProfile'){await api('/api/profiles','POST',{name:data.get('name'),avatar:data.get('avatar'),isKid:data.get('isKid')==='on'});await reload();S.modal=null;S.accountTab='profiles';render();toast('Perfil criado.');return;}
if(type==='review'){await api('/api/reviews','POST',{movieId:Number(form.dataset.id),stars:Number(data.get('stars')),body:String(data.get('body')||'')});await details(Number(form.dataset.id));toast('Avaliação salva!');return;}
if(type==='planPrice'){await api(`/api/admin/plans/${form.dataset.id}`,'PATCH',{priceCents:Number(data.get('priceCents'))});await reload();await loadAdmin();render();toast('Preço atualizado.');return;}
if(type==='createMovie'){const poster=await upload(data.get('posterFile')?.size?data.get('posterFile'):null,'poster');const video=await upload(data.get('videoFile')?.size?data.get('videoFile'):null,'video');const payload={title:String(data.get('title')||''),slug:String(data.get('slug')||''),synopsis:String(data.get('synopsis')||''),year:Number(data.get('year')||2026),durationSec:Number(data.get('durationSec')||300),accessType:String(data.get('accessType')),rentalCents:Number(data.get('rentalCents')||0),ageRating:Number(data.get('ageRating')||0),director:String(data.get('director')||''),castText:String(data.get('castText')||''),genres:String(data.get('genres')||'').split(',').map(x=>x.trim()).filter(Boolean),poster:poster||'/assets/posters/01.svg',videoFile:video||'cafe-das-estrelas.mp4'};
await api('/api/admin/movies','POST',payload);await reload();await loadAdmin();render();toast('Filme cadastrado e publicado.');return;}
}catch(e){if(type==='auth'){S.authError=e.message;const el=form.querySelector('.auth-error');if(el){el.hidden=false;el.textContent=e.message;}}showError(e);}}
document.addEventListener('click',async e=>{const btn=e.target.closest('[data-action]');if(!btn)return;if(btn.dataset.action==='closeOnBackdrop'&&e.target!==btn)return;e.preventDefault();if(S.busy)return;S.busy=true;try{await handleAction(btn,e);}finally{S.busy=false;}});
document.addEventListener('submit',async e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();if(S.busy)return;S.busy=true;const submit=form.querySelector('button[type="submit"],button:not([type])');const previous=submit?.textContent;if(submit){submit.disabled=true;if(form.dataset.form==='auth')submit.textContent=S.authMode==='register'?'Criando sua conta...':'Entrando...';}try{await handleForm(form);}finally{S.busy=false;if(submit?.isConnected){submit.disabled=false;submit.textContent=previous;}}});
document.addEventListener('change',async e=>{if(e.target.matches('[data-password-toggle]')){const mode=e.target.checked?'text':'password';document.querySelectorAll('form[data-form=auth] input[type=password],form[data-form=auth] input[name=password],form[data-form=auth] input[name=confirmPassword]').forEach(n=>n.type=mode);return;}if(!['genreFilter','decadeFilter','accessFilter','sortFilter'].includes(e.target.id))return;S.genre=document.getElementById('genreFilter')?.value||'';S.decade=document.getElementById('decadeFilter')?.value||'';S.access=document.getElementById('accessFilter')?.value||'';S.sort=document.getElementById('sortFilter')?.value||'recent';await updateCatalog();render();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&S.modal)closeModal();if(e.key==='Enter'&&e.target.matches('.movie-card')){e.preventDefault();details(e.target.dataset.id);}});
(async()=>{try{if(location.protocol==='file:')throw new Error('Este aplicativo precisa ser aberto pelo servidor local, e não clicando duas vezes em index.html.');await reload();render();}catch(e){root.innerHTML=`<div class="container" style="padding:90px 0"><h1 class="page-title">Não conseguimos abrir o cinema</h1><p>${esc(e.message)}</p><p>Para ativar o cadastro e o login, extraia o ZIP e abra <strong>INICIAR_RETRO_PLAY.bat</strong>. Depois acesse <strong>http://127.0.0.1:4173</strong>.</p><button onclick="location.reload()" class="btn btn-primary">Tentar novamente</button></div>`;}})();
